function card(title,body){return '<section class="panel"><div class="panelHead"><h2>'+title+'</h2></div>'+body+'</section>'}
function stat(label,value,sub,cls){return '<div class="stat"><span>'+label+'</span><strong class="'+(cls||"")+'">'+value+'</strong><small>'+sub+'</small></div>'}
function spendable(){return data.accounts.filter(function(a){return a.currency==="EUR"&&a.type!=="Credit Card"&&a.includeInSafeSpend!==false}).reduce(function(s,a){return s+N(a.balance)},0)}
function recurring(){return data.recurring.filter(function(x){return x.currency==="EUR"}).reduce(function(s,x){return s+N(x.amount)},0)}
function loanModel(pay){pay=N(pay)||N(data.loan.payment);var b=N(data.loan.opening),rate=N(data.loan.rate)/100,int=0,n=0,d=new Date((data.loan.start||"2026-10-11")+"T00:00:00"),rows=[];while(b>.01&&n<240){var it=n===0?17967:b*rate,p=Math.min(pay,b+it),pr=Math.max(0,p-it);b=Math.max(0,b-pr);int+=it;n++;rows.push({n:n,date:d.toISOString().slice(0,10),payment:p,interest:it,principal:pr,closing:b});d.setMonth(d.getMonth()+1)}return{rows:rows,interest:int,payoff:rows.at(-1)?rows.at(-1).date:""}}
function setTitle(t){$("pageTitle").textContent=t}
function navActive(id){document.querySelectorAll("[data-nav]").forEach(function(b){b.classList.toggle("active",b.dataset.nav===id)})}

function dashboard(){
 var k=curMonth(),m=data.months[k]||{},left=N(m.income)-spend(k),safe=spendable()-recurring()-1000,ks=months().slice(-6),mx=Math.max.apply(null,ks.map(spend).concat([1]));
 var bars=ks.map(function(x){return '<div class="barItem"><div class="barValue">'+E(spend(x))+'</div><div class="barTrack"><i style="height:'+Math.max(4,spend(x)/mx*150)+'px"></i></div><span>'+mlabel(x).slice(0,3)+'</span></div>'}).join("");
 var cats=Object.entries(m.actual||{}).sort(function(a,b){return b[1]-a[1]}).slice(0,6),bl=cats.map(function(x){var b=N((m.budget||{})[x[0]]),p=b?Math.min(100,x[1]/b*100):0;return '<div class="budgetLine"><div><span>'+esc(x[0])+'</span><b>'+E(x[1])+(b?" / "+E(b):"")+'</b></div><div class="progress"><i style="width:'+p+'%"></i></div></div>'}).join("");
 var tx=data.transactions.slice().sort(function(a,b){return String(b.date).localeCompare(String(a.date))}).slice(0,8),txh=tx.length?tx.map(function(t){return '<div class="txRow"><div class="txIcon">'+(t.type==="income"?"↑":"−")+'</div><div><b>'+esc(t.description||"Transaction")+'</b><small>'+esc(t.category||"Other")+' · '+dateText(t.date)+'</small></div><strong class="'+(t.type==="income"?"positive":"")+'">'+(t.type==="income"?"+":"−")+(t.currency==="INR"?R(t.amount):E(t.amount))+'</strong></div>'}).join(""):'<div class="empty">No transactions yet. Add your first transaction to build the ledger.</div>';
 var alerts=[],cc=data.creditCard;if(left<0)alerts.push('<div class="alert danger"><b>Current month is above income</b><span>'+E(Math.abs(left))+' more has been recorded than income.</span></div>');if(safe<0)alerts.push('<div class="alert danger"><b>Safe-to-spend is below reserve</b><span>Recurring commitments plus the €1,000 reserve exceed spendable cash.</span></div>');if(cc.limit&&cc.balance/cc.limit>.8)alerts.push('<div class="alert warning"><b>Credit card utilisation is high</b><span>Review the current balance before discretionary spending.</span></div>');if(!alerts.length)alerts.push('<div class="alert good"><b>No active alerts</b><span>Your stored rules are not flagging anything urgent.</span></div>');
 $("pfContent").innerHTML='<div class="heroRow"><div><div class="eyebrow">CURRENT PERIOD</div><h2>'+esc(m.label||mlabel(k))+'</h2><p>Cash, income, spending and decisions in one place.</p></div><div class="actions"><button data-action="addIncome">+ Income</button><button class="primary" data-action="addTx">+ Expense</button></div></div>'+
 '<div class="statsGrid">'+stat("Income",E(m.income),"Period income")+stat("Spending",E(spend(k)),"Recorded expenses")+stat("Left this month",E(left),left<0?"Above income":"After recorded spending",left<0?"negative":"positive")+stat("Safe to spend",E(safe),"After recurring + €1,000 reserve",safe<0?"negative":"positive")+'</div>'+card("Money at a glance",'<div class="simpleList"><div><span>AIB Regular Account</span><b>'+E((data.accounts.find(function(a){return a.id==="aib-regular"})||{}).balance||0)+'</b></div><div><span>Avant Money Everyday Credit Card</span><b class="'+(N(data.creditCard.balance)>0?"negative":"")+'">'+E(N(data.creditCard.balance))+'</b></div><div><span>AIB Savings</span><b>'+E((data.accounts.find(function(a){return a.id==="aib-savings"})||{}).balance||0)+'</b></div></div><div class="actions"><button data-action="addIncome">+ Record income</button><button data-nav="accounts">Manage accounts →</button></div>')+
 '<div class="dashboardGrid">'+card("Cash flow",'<div class="chartLegend"><span>Monthly spending</span><span>Last 6 months</span></div><div class="barChart">'+bars+'</div>')+
 card("Budget status",bl||'<div class="empty">No budget data yet.</div><button class="linkBtn" data-nav="budget">View budget →</button>')+'</div>'+
 '<div class="dashboardGrid lower">'+card("Latest transactions",'<div>'+txh+'</div><button class="linkBtn" data-nav="transactions">Open full ledger →</button>')+card("Needs attention",alerts.join(""))+'</div>';
}
